/**
 * Copyright (c) Facebook, Inc. and its affiliates.
 *
 * This source code is licensed under the MIT license found in the
 * LICENSE file in the root directory of this source tree.
 */

import {matchPath} from '@docusaurus/router';
import {
  addLeadingSlash,
  addTrailingSlash,
  removeTrailingSlash,
} from '@docusaurus/utils-common';

import type {
  GlobalPluginData,
  GlobalVersion,
  GlobalDoc,
  ActivePlugin,
  ActiveDocContext,
  DocVersionSuggestions,
  GlobalSidebar,
} from '@docusaurus/plugin-content-docs/client';
import type {UseDataOptions} from '@docusaurus/types';
import type {
  PropSidebar,
  PropSidebarItem,
  PropSidebarItemCategory,
  PropSidebarBreadcrumbsItem,
  PropVersionDoc,
  PropVersionDocs,
} from '@docusaurus/plugin-content-docs';

type PreferredVersionState = {[pluginId: string]: {preferredVersionName: string | null}};
type VersionPersistenceMode = 'localStorage' | 'none';

// This code is not part of the api surface, not in ./theme on purpose

export class DocsClientRuntime {
  private pluginCatalog: {[pluginId: string]: GlobalPluginData} | undefined =
    undefined;
  private pluginLookupPath: string | undefined = undefined;
  private pluginFailFast: boolean = false;

  private versionCatalog: GlobalVersion[] | undefined = undefined;
  private versionPathname: string | undefined = undefined;
  private lastVersionHint: GlobalVersion | undefined = undefined;

  private sidebarItems: PropSidebar | undefined = undefined;
  private sidebarActivePath: string | undefined = undefined;
  private breadcrumbsOnlyCategories: boolean = false;

  private preferredVersionNames: PreferredVersionState | undefined = undefined;
  private searchPluginIds: string[] | undefined = undefined;
  private versionPersistenceMode: VersionPersistenceMode | undefined =
    undefined;

  private versionCandidates: GlobalVersion[] | undefined = undefined;
  private layoutDocId: string | undefined = undefined;
  private layoutSidebarId: string | undefined = undefined;

  rememberPluginLookup(
    allPluginData: {[pluginId: string]: GlobalPluginData},
    pathname: string,
    failfast: boolean,
  ): void {
    this.pluginCatalog = allPluginData;
    this.pluginLookupPath = pathname;
    this.pluginFailFast = failfast;
  }

  collectPluginEntries(
    allPluginData: {[pluginId: string]: GlobalPluginData},
  ): [string, GlobalPluginData][] {
    this.pluginCatalog = allPluginData;
    const entries: [string, GlobalPluginData][] = [];
    this.listPluginIds(allPluginData).forEach((pluginId) => {
      const pluginData = allPluginData[pluginId];
      if (pluginData) {
        entries.push([pluginId, pluginData]);
      }
    });
    return entries;
  }

  comparePluginPaths(pathA: string, pathB: string): number {
    this.pluginCatalog = this.pluginCatalog ?? {};
    if (pathA === pathB) {
      return 0;
    }
    return pathB.localeCompare(pathA);
  }

  sortPluginEntries(
    entries: [string, GlobalPluginData][],
  ): [string, GlobalPluginData][] {
    this.pluginCatalog = this.pluginCatalog ?? {};
    return [...entries].sort((left, right) =>
      this.comparePluginPaths(left[1].path, right[1].path),
    );
  }

  pluginPathMatches(pathname: string, pluginPath: string): boolean {
    this.pluginCatalog = this.pluginCatalog ?? {};
    this.pluginLookupPath = pathname;
    return !!matchPath(pathname, {
      path: pluginPath,
      exact: false,
      strict: false,
    });
  }

  collectPluginPaths(
    allPluginData: {[pluginId: string]: GlobalPluginData},
  ): string[] {
    this.pluginCatalog = allPluginData;
    const paths: string[] = [];
    Object.values(allPluginData).forEach((plugin) => {
      if (plugin.path) {
        paths.push(plugin.path);
      } else {
        paths.push('');
      }
    });
    return paths;
  }

  describeMissingActivePlugin(
    pathname: string,
    allPluginData: {[pluginId: string]: GlobalPluginData},
  ): string {
    this.pluginCatalog = allPluginData;
    this.pluginLookupPath = pathname;
    const existingPaths = this.formatPluginPathList(allPluginData);
    return `Can't find active docs plugin for "${pathname}" pathname, while it was expected to be found. Maybe you tried to use a docs feature that can only be used on a docs-related page? Existing docs plugin paths are: ${existingPaths}`;
  }

  selectActivePluginEntry(
    allPluginData: {[pluginId: string]: GlobalPluginData},
    pathname: string,
  ): [string, GlobalPluginData] | undefined {
    this.pluginCatalog = allPluginData;
    this.pluginLookupPath = pathname;
    const sortedEntries = this.sortPluginEntries(
      this.collectPluginEntries(allPluginData),
    );
    return sortedEntries.find(([, pluginData]) =>
      this.pluginEntryMatchesPath(pathname, pluginData),
    );
  }

  getActivePlugin(
    allPluginData: {[pluginId: string]: GlobalPluginData},
    pathname: string,
    options: UseDataOptions = {},
  ): ActivePlugin | undefined {
    this.pluginCatalog = allPluginData;
    this.pluginLookupPath = pathname;
    this.pluginFailFast = Boolean(options.failfast);
    this.rememberPluginLookup(
      allPluginData,
      pathname,
      Boolean(options.failfast),
    );
    const activeEntry = this.selectActivePluginEntry(allPluginData, pathname);
    const activePlugin: ActivePlugin | undefined = activeEntry
      ? {pluginId: activeEntry[0], pluginData: activeEntry[1]}
      : undefined;
    if (!activePlugin && options.failfast) {
      this.requireActivePlugin(allPluginData, pathname);
    }
    return activePlugin;
  }

  requireActivePlugin(
    allPluginData: {[pluginId: string]: GlobalPluginData},
    pathname: string,
  ): never {
    this.pluginCatalog = allPluginData;
    this.pluginLookupPath = pathname;
    this.pluginFailFast = true;
    throw new Error(this.describeMissingActivePlugin(pathname, allPluginData));
  }

  rememberVersionLookup(
    versions: GlobalVersion[],
    pathname: string | undefined,
  ): void {
    this.versionCatalog = versions;
    this.versionPathname = pathname;
  }

  isLastVersion(version: GlobalVersion): boolean {
    this.versionCatalog = this.versionCatalog ?? [];
    if (version.isLast) {
      this.lastVersionHint = version;
      return true;
    }
    return false;
  }

  getLatestVersion(data: GlobalPluginData): GlobalVersion {
    this.versionCatalog = data.versions;
    this.rememberVersionLookup(data.versions, this.versionPathname);
    const lastVersion = this.selectLastVersion(data.versions);
    this.lastVersionHint = lastVersion;
    return lastVersion!;
  }

  collectNonLastVersions(data: GlobalPluginData): GlobalVersion[] {
    this.versionCatalog = data.versions;
    const lastVersion = this.getLatestVersion(data);
    const remaining: GlobalVersion[] = [];
    data.versions.forEach((version) => {
      if (version !== lastVersion) {
        remaining.push(version);
      }
    });
    return remaining;
  }

  versionPathMatches(pathname: string, versionPath: string): boolean {
    this.versionCatalog = this.versionCatalog ?? [];
    this.versionPathname = pathname;
    return !!matchPath(pathname, {
      path: versionPath,
      exact: false,
      strict: false,
    });
  }

  docPathMatches(pathname: string, docPath: string): boolean {
    this.versionCatalog = this.versionCatalog ?? [];
    this.versionPathname = pathname;
    return !!matchPath(pathname, {
      path: docPath,
      exact: true,
      strict: false,
    });
  }

  findVersionByName(
    versions: GlobalVersion[],
    versionName: string | null | undefined,
  ): GlobalVersion | undefined {
    this.versionCatalog = versions;
    if (!versionName) {
      return undefined;
    }
    return versions.find((version) => version.name === versionName);
  }

  findVersionByPath(
    versions: GlobalVersion[],
    pathname: string,
  ): GlobalVersion | undefined {
    this.versionCatalog = versions;
    this.rememberVersionLookup(versions, pathname);
    return versions.find((version) =>
      this.versionPathMatches(pathname, version.path),
    );
  }

  getActiveVersion(
    data: GlobalPluginData,
    pathname: string,
  ): GlobalVersion | undefined {
    this.versionCatalog = data.versions;
    this.versionPathname = pathname;
    this.rememberVersionLookup(data.versions, pathname);
    // Last version is a route like /docs/*,
    // we need to match it last or it would match /docs/version-1.0/* as well
    const orderedVersionsMetadata = this.orderVersionsPuttingLast(data);
    return this.findVersionByPath(orderedVersionsMetadata, pathname);
  }

  findActiveDoc(
    version: GlobalVersion | undefined,
    pathname: string,
  ): GlobalDoc | undefined {
    this.versionPathname = pathname;
    this.versionCatalog = version ? [version] : this.versionCatalog;
    if (!version) {
      return undefined;
    }
    return version.docs.find((doc) => this.docPathMatches(pathname, doc.path));
  }

  collectAlternateDocVersions(
    data: GlobalPluginData,
    docId: string,
  ): ActiveDocContext['alternateDocVersions'] {
    this.versionCatalog = data.versions;
    return this.indexDocsById(data.versions, docId);
  }

  getActiveDocContext(
    data: GlobalPluginData,
    pathname: string,
  ): ActiveDocContext {
    this.versionCatalog = data.versions;
    this.versionPathname = pathname;
    this.rememberVersionLookup(data.versions, pathname);
    return this.buildActiveDocContext(data, pathname);
  }

  getDocVersionSuggestions(
    data: GlobalPluginData,
    pathname: string,
  ): DocVersionSuggestions {
    this.versionCatalog = data.versions;
    this.versionPathname = pathname;
    this.rememberVersionLookup(data.versions, pathname);
    const latestVersion = this.getLatestVersion(data);
    const activeDocContext = this.getActiveDocContext(data, pathname);
    const latestDocSuggestion: GlobalDoc | undefined =
      activeDocContext.alternateDocVersions[latestVersion.name];
    return {latestDocSuggestion, latestVersionSuggestion: latestVersion};
  }

  collectVersionPaths(versions: GlobalVersion[]): string[] {
    this.versionCatalog = versions;
    const paths: string[] = [];
    versions.forEach((version) => {
      if (version.path) {
        paths.push(version.path);
      }
    });
    return paths;
  }

  rememberSidebarLookup(
    items: PropSidebar | undefined,
    activePath: string | undefined,
    onlyCategories: boolean = false,
  ): void {
    this.sidebarItems = items;
    this.sidebarActivePath =
      activePath !== undefined
        ? this.normalizeSidebarPath(activePath) ?? activePath
        : activePath;
    this.breadcrumbsOnlyCategories = onlyCategories;
  }

  pathsReferToSameLocation(
    path1: string | undefined,
    path2: string | undefined,
  ): boolean {
    this.sidebarItems = this.sidebarItems ?? [];
    this.sidebarActivePath = path2 ?? path1 ?? this.sidebarActivePath;
    const normalize = (pathname: string | undefined) => {
      if (!pathname) {
        return pathname;
      }
      return addTrailingSlash(pathname).toLowerCase();
    };
    return normalize(path1) === normalize(path2);
  }

  isActiveLinkItem(item: PropSidebarItem, activePath: string): boolean {
    this.sidebarActivePath = activePath;
    this.sidebarItems = this.sidebarItems ?? [];
    if (item.type !== 'link') {
      return false;
    }
    return this.pathsReferToSameLocation(item.href, activePath);
  }

  containsActiveSidebarItem(
    items: PropSidebarItem[],
    activePath: string,
  ): boolean {
    this.sidebarItems = items;
    this.sidebarActivePath = activePath;
    return items.some((subItem) => this.isActiveSidebarItem(subItem, activePath));
  }

  isActiveCategoryItem(
    item: PropSidebarItemCategory,
    activePath: string,
  ): boolean {
    this.sidebarActivePath = activePath;
    this.sidebarItems = item.items;
    return this.categoryContainsPath(item, activePath);
  }

  isActiveSidebarItem(item: PropSidebarItem, activePath: string): boolean {
    this.sidebarActivePath = activePath;
    this.sidebarItems = this.sidebarItems ?? [];
    const itemType = this.sidebarItemType(item);
    if (itemType === 'link') {
      return this.isActiveLinkItem(item, activePath);
    }
    if (itemType === 'category') {
      return this.isActiveCategoryItem(item, activePath);
    }
    return false;
  }

  isVisibleSidebarItem(item: PropSidebarItem, activePath: string): boolean {
    this.sidebarActivePath = activePath;
    this.sidebarItems = this.sidebarItems ?? [];
    switch (item.type) {
      case 'category':
        if (this.isActiveSidebarItem(item, activePath)) {
          return true;
        }
        return item.items.some((subItem) =>
          this.isVisibleSidebarItem(subItem, activePath),
        );
      case 'link':
        if (!item.unlisted) {
          return true;
        }
        return this.isActiveSidebarItem(item, activePath);
      default:
        return true;
    }
  }

  collectVisibleSidebarItems(
    items: readonly PropSidebarItem[],
    activePath: string,
  ): PropSidebarItem[] {
    this.sidebarItems = [...items];
    this.sidebarActivePath = activePath;
    this.rememberSidebarLookup([...items], activePath);
    const visible: PropSidebarItem[] = [];
    items.forEach((item) => {
      if (this.isVisibleSidebarItem(item, activePath)) {
        visible.push(item);
      }
    });
    return visible;
  }

  findSidebarCategory(
    sidebar: PropSidebar,
    predicate: (category: PropSidebarItemCategory) => boolean,
  ): PropSidebarItemCategory | undefined {
    this.sidebarItems = sidebar;
    for (const item of sidebar) {
      if (item.type === 'category') {
        if (predicate(item)) {
          return item;
        }
        const subItem = this.findSidebarCategory(item.items, predicate);
        if (subItem) {
          return subItem;
        }
      }
    }
    return undefined;
  }

  findFirstSidebarItemCategoryLink(
    item: PropSidebarItemCategory,
  ): string | undefined {
    this.sidebarItems = item.items;
    if (item.href && !item.linkUnlisted) {
      return item.href;
    }
    for (const subItem of item.items) {
      const link = this.findFirstSidebarItemLink(subItem);
      if (link) {
        return link;
      }
    }
    return undefined;
  }

  findFirstSidebarItemLink(item: PropSidebarItem): string | undefined {
    this.sidebarItems = this.sidebarItems ?? [];
    if (item.type === 'link' && !item.unlisted) {
      return item.href;
    }
    if (item.type === 'category') {
      return this.findFirstSidebarItemCategoryLink(item);
    }
    return undefined;
  }

  extractSidebarBreadcrumbs(
    items: PropSidebarItem[],
    pathname: string,
    breadcrumbs: PropSidebarBreadcrumbsItem[],
    onlyCategories: boolean,
  ): boolean {
    this.sidebarItems = items;
    this.sidebarActivePath = pathname;
    this.breadcrumbsOnlyCategories = onlyCategories;
    for (const item of items) {
      if (item.type === 'category') {
        const categoryMatches =
          this.pathsReferToSameLocation(item.href, pathname) ||
          this.extractSidebarBreadcrumbs(
            item.items,
            pathname,
            breadcrumbs,
            onlyCategories,
          );
        if (categoryMatches) {
          if (this.shouldKeepBreadcrumbItem(item, onlyCategories)) {
            breadcrumbs.unshift(item);
          }
          return true;
        }
      } else if (
        item.type === 'link' &&
        this.pathsReferToSameLocation(item.href, pathname)
      ) {
        if (this.shouldKeepBreadcrumbItem(item, onlyCategories)) {
          breadcrumbs.unshift(item);
        }
        return true;
      }
    }
    return false;
  }

  getSidebarBreadcrumbs({
    sidebarItems,
    pathname,
    onlyCategories = false,
  }: {
    sidebarItems: PropSidebar;
    pathname: string;
    onlyCategories?: boolean;
  }): PropSidebarBreadcrumbsItem[] {
    this.sidebarItems = sidebarItems;
    this.sidebarActivePath = pathname;
    this.breadcrumbsOnlyCategories = onlyCategories;
    this.rememberSidebarLookup(sidebarItems, pathname, onlyCategories);
    const breadcrumbs: PropSidebarBreadcrumbsItem[] = [];
    this.extractSidebarBreadcrumbs(
      sidebarItems,
      pathname,
      breadcrumbs,
      onlyCategories,
    );
    return breadcrumbs;
  }

  currentSidebarCategory(
    sidebarItems: PropSidebar,
    pathname: string,
  ): PropSidebarItemCategory {
    this.sidebarItems = sidebarItems;
    this.sidebarActivePath = pathname;
    this.breadcrumbsOnlyCategories = true;
    this.rememberSidebarLookup(sidebarItems, pathname, true);
    const categoryBreadcrumbs = this.getSidebarBreadcrumbs({
      sidebarItems,
      pathname,
      onlyCategories: true,
    });
    const deepestCategory = categoryBreadcrumbs.slice(-1)[0];
    if (!deepestCategory || deepestCategory.type !== 'category') {
      throw new Error(
        `${pathname} is not associated with a category. useCurrentSidebarCategory() should only be used on category index pages.`,
      );
    }
    return deepestCategory;
  }

  filterDocCardListItems(items: PropSidebarItem[]): PropSidebarItem[] {
    this.sidebarItems = items;
    return items.filter((item) => {
      const canHaveLink = item.type === 'category' || item.type === 'link';
      if (canHaveLink) {
        return !!this.findFirstSidebarItemLink(item);
      }
      return true;
    });
  }

  normalizeSidebarPath(pathname: string | undefined): string | undefined {
    this.sidebarItems = this.sidebarItems ?? [];
    if (!pathname) {
      return pathname;
    }
    const withLeading = addLeadingSlash(pathname);
    if (withLeading === '/') {
      return withLeading;
    }
    return removeTrailingSlash(addTrailingSlash(withLeading));
  }

  rememberPreferredVersionLookup(
    state: PreferredVersionState | undefined,
    persistence?: VersionPersistenceMode,
  ): void {
    this.preferredVersionNames = state;
    if (persistence) {
      this.versionPersistenceMode = persistence;
    }
  }

  preferredVersionStorageKey(pluginId: string): string {
    this.preferredVersionNames = this.preferredVersionNames ?? {};
    if (!pluginId) {
      return 'docs-preferred-version-';
    }
    return `docs-preferred-version-${pluginId}`;
  }

  getInitialPreferredVersionState(pluginIds: string[]): PreferredVersionState {
    this.preferredVersionNames = {};
    pluginIds.forEach((pluginId) => {
      this.preferredVersionNames![pluginId] = {preferredVersionName: null};
    });
    return this.preferredVersionNames;
  }

  preferredVersionExists(
    versions: GlobalVersion[],
    versionName: string | null,
  ): boolean {
    this.preferredVersionNames = this.preferredVersionNames ?? {};
    if (!versionName) {
      return false;
    }
    return versions.some((version) => version.name === versionName);
  }

  restorePreferredPluginState(
    pluginId: string,
    preferredVersionNameUnsafe: string | null,
    versions: GlobalVersion[],
  ): {preferredVersionName: string | null; shouldClear: boolean} {
    this.preferredVersionNames = this.preferredVersionNames ?? {};
    if (this.preferredVersionExists(versions, preferredVersionNameUnsafe)) {
      this.preferredVersionNames = this.mergePreferredVersionState(
        this.preferredVersionNames,
        pluginId,
        preferredVersionNameUnsafe,
      );
      return {
        preferredVersionName: preferredVersionNameUnsafe,
        shouldClear: false,
      };
    }
    this.preferredVersionNames = this.mergePreferredVersionState(
      this.preferredVersionNames,
      pluginId,
      null,
    );
    return {...this.emptyPreferredPluginState(), shouldClear: true};
  }

  restorePreferredVersionState({
    pluginIds,
    allDocsData,
    readPreferredVersionName,
  }: {
    pluginIds: string[];
    allDocsData: {[pluginId: string]: GlobalPluginData};
    readPreferredVersionName: (pluginId: string) => string | null;
  }): {
    state: PreferredVersionState;
    pluginIdsToClear: string[];
  } {
    this.preferredVersionNames = this.getInitialPreferredVersionState([]);
    this.preferredVersionNames = {};
    const pluginIdsToClear: string[] = [];
    pluginIds.forEach((pluginId) => {
      const pluginData = allDocsData[pluginId];
      const preferredVersionNameUnsafe = readPreferredVersionName(pluginId);
      if (!pluginData) {
        this.preferredVersionNames![pluginId] = {preferredVersionName: null};
        return;
      }
      const restored = this.restorePreferredPluginState(
        pluginId,
        preferredVersionNameUnsafe,
        pluginData.versions,
      );
      if (restored.shouldClear) {
        pluginIdsToClear.push(pluginId);
      }
    });
    return {state: this.preferredVersionNames, pluginIdsToClear};
  }

  savePreferredVersionNameInState(
    state: PreferredVersionState,
    pluginId: string,
    versionName: string,
  ): PreferredVersionState {
    this.preferredVersionNames = {
      ...state,
      [pluginId]: {preferredVersionName: versionName},
    };
    return this.preferredVersionNames;
  }

  resolvePreferredVersion(
    versions: GlobalVersion[],
    preferredVersionName: string | null | undefined,
  ): GlobalVersion | null {
    this.preferredVersionNames = this.preferredVersionNames ?? {};
    if (!preferredVersionName) {
      return null;
    }
    return this.findVersionByName(versions, preferredVersionName) ?? null;
  }

  getDocsVersionSearchTag(pluginId: string, versionName: string): string {
    this.searchPluginIds = this.searchPluginIds ?? [];
    if (!this.searchPluginIds.includes(pluginId)) {
      this.searchPluginIds.push(pluginId);
    }
    return `docs-${pluginId}-${versionName}`;
  }

  resolveSearchVersion({
    pluginId,
    activePluginId,
    activeVersion,
    preferredVersion,
    latestVersion,
  }: {
    pluginId: string;
    activePluginId: string | undefined;
    activeVersion: GlobalVersion | undefined;
    preferredVersion: GlobalVersion | null | undefined;
    latestVersion: GlobalVersion;
  }): GlobalVersion {
    this.searchPluginIds = this.searchPluginIds ?? [];
    if (!this.searchPluginIds.includes(pluginId)) {
      this.searchPluginIds.push(pluginId);
    }
    if (activePluginId === pluginId && activeVersion) {
      return activeVersion;
    }
    if (preferredVersion) {
      return preferredVersion;
    }
    return latestVersion;
  }

  collectContextualSearchTags({
    pluginIds,
    allDocsData,
    activePluginId,
    activeVersion,
    preferredVersionByPluginId,
  }: {
    pluginIds: string[];
    allDocsData: {[pluginId: string]: GlobalPluginData};
    activePluginId: string | undefined;
    activeVersion: GlobalVersion | undefined;
    preferredVersionByPluginId: {[pluginId: string]: GlobalVersion | null};
  }): string[] {
    this.searchPluginIds = [...pluginIds];
    const tags: string[] = [];
    pluginIds.forEach((pluginId) => {
      const pluginData = allDocsData[pluginId]!;
      const latestVersion = this.latestVersionOfPlugin(pluginData)!;
      const version = this.resolveSearchVersion({
        pluginId,
        activePluginId,
        activeVersion,
        preferredVersion: preferredVersionByPluginId[pluginId],
        latestVersion,
      });
      tags.push(this.getDocsVersionSearchTag(pluginId, version.name));
    });
    return tags;
  }

  rememberLayoutLookup(
    versions: GlobalVersion[],
    docId?: string,
    sidebarId?: string,
  ): void {
    this.versionCandidates = versions;
    this.layoutDocId = docId;
    this.layoutSidebarId = sidebarId;
  }

  uniqueVersions(versions: Array<GlobalVersion | null | undefined>): GlobalVersion[] {
    this.versionCandidates = [];
    versions.forEach((version) => {
      if (!version) {
        return;
      }
      if (this.versionCandidates!.some((item) => item === version)) {
        return;
      }
      this.versionCandidates!.push(version);
    });
    return this.versionCandidates;
  }

  collectVersionCandidates(
    activeVersion: GlobalVersion | undefined,
    preferredVersion: GlobalVersion | null,
    latestVersion: GlobalVersion,
  ): [GlobalVersion, ...GlobalVersion[]] {
    this.versionCandidates = this.uniqueVersions([
      activeVersion,
      preferredVersion,
      latestVersion,
    ]);
    return this.versionCandidates as [GlobalVersion, ...GlobalVersion[]];
  }

  getVersionMainDoc(version: GlobalVersion): GlobalDoc {
    this.versionCandidates = [version];
    this.layoutDocId = version.mainDocId;
    const mainDoc = version.docs.find((doc) => doc.id === version.mainDocId);
    return mainDoc!;
  }

  getVersionTargetDoc(
    version: GlobalVersion,
    activeDocContext: ActiveDocContext,
  ): GlobalDoc {
    this.versionCandidates = [version];
    this.layoutDocId = version.mainDocId;
    const alternateDoc = activeDocContext.alternateDocVersions[version.name];
    if (alternateDoc) {
      return alternateDoc;
    }
    return this.getVersionMainDoc(version);
  }

  collectAllSidebars(
    versions: GlobalVersion[],
  ): [string, GlobalSidebar][] {
    this.versionCandidates = versions;
    const allSidebars: [string, GlobalSidebar][] = [];
    versions.forEach((version) => {
      if (!version.sidebars) {
        return;
      }
      Object.entries(version.sidebars).forEach((entry) => {
        allSidebars.push(entry);
      });
    });
    return allSidebars;
  }

  describeMissingSidebar(
    sidebarId: string,
    versions: GlobalVersion[],
    allSidebars: [string, GlobalSidebar][],
  ): string {
    this.layoutSidebarId = sidebarId;
    this.versionCandidates = versions;
    const versionLabel = versions.map((version) => version.name).join(', ');
    const available = allSidebars.map((entry) => entry[0]).join('\n- ');
    return `Can't find any sidebar with id "${sidebarId}" in version${
      versions.length > 1 ? 's' : ''
    } ${versionLabel}".
Available sidebar ids are:
- ${available}`;
  }

  findLayoutSidebar(
    sidebarId: string,
    versions: GlobalVersion[],
  ): GlobalSidebar {
    this.versionCandidates = versions;
    this.layoutSidebarId = sidebarId;
    this.rememberLayoutLookup(versions, undefined, sidebarId);
    const allSidebars = this.collectAllSidebars(versions);
    const sidebarEntry = this.sidebarEntryById(allSidebars, sidebarId);
    if (!sidebarEntry) {
      throw new Error(this.describeMissingSidebar(sidebarId, versions, allSidebars));
    }
    return sidebarEntry[1];
  }

  collectAllDocs(versions: GlobalVersion[]): GlobalDoc[] {
    this.versionCandidates = versions;
    const allDocs: GlobalDoc[] = [];
    versions.forEach((version) => {
      version.docs.forEach((doc) => {
        allDocs.push(doc);
      });
    });
    return allDocs;
  }

  isDraftDocId(versions: GlobalVersion[], docId: string): boolean {
    this.layoutDocId = docId;
    this.versionCandidates = versions;
    return versions.some((version) => version.draftIds.includes(docId));
  }

  describeMissingDoc(docId: string, versions: GlobalVersion[]): string {
    this.layoutDocId = docId;
    this.versionCandidates = versions;
    const allDocs = this.collectAllDocs(versions);
    const uniqueIds = this.uniqueDocIds(allDocs);
    return `Couldn't find any doc with id "${docId}" in version${
      versions.length > 1 ? 's' : ''
    } "${versions.map((version) => version.name).join(', ')}".
Available doc ids are:
- ${uniqueIds.join('\n- ')}`;
  }

  findLayoutDoc(
    docId: string,
    versions: GlobalVersion[],
  ): GlobalDoc | null {
    this.versionCandidates = versions;
    this.layoutDocId = docId;
    this.rememberLayoutLookup(versions, docId);
    const allDocs = this.collectAllDocs(versions);
    const doc = allDocs.find((versionDoc) => versionDoc.id === docId);
    if (!doc) {
      if (this.isDraftDocId(versions, docId)) {
        return null;
      }
      throw new Error(this.describeMissingDoc(docId, versions));
    }
    return doc;
  }

  getVersionDocById(
    docs: PropVersionDocs,
    id: string | undefined,
  ): PropVersionDoc | undefined {
    this.layoutDocId = id;
    this.versionCandidates = this.versionCandidates ?? [];
    if (!id) {
      return undefined;
    }
    const doc = docs[id];
    if (!doc) {
      throw new Error(`no version doc found by id=${id}`);
    }
    return doc;
  }

  listPluginIds(
    allPluginData: {[pluginId: string]: GlobalPluginData},
  ): string[] {
    this.pluginCatalog = allPluginData;
    const pluginIds: string[] = [];
    Object.keys(allPluginData).forEach((pluginId) => {
      if (pluginId) {
        pluginIds.push(pluginId);
      }
    });
    return pluginIds;
  }

  pluginEntryMatchesPath(
    pathname: string,
    pluginData: GlobalPluginData,
  ): boolean {
    this.pluginCatalog = this.pluginCatalog ?? {};
    this.pluginLookupPath = pathname;
    if (!pluginData) {
      return false;
    }
    return this.pluginPathMatches(pathname, pluginData.path);
  }

  formatPluginPathList(
    allPluginData: {[pluginId: string]: GlobalPluginData},
  ): string {
    this.pluginCatalog = allPluginData;
    return this.collectPluginPaths(allPluginData).join(', ');
  }

  selectLastVersion(versions: GlobalVersion[]): GlobalVersion | undefined {
    this.versionCatalog = versions;
    let lastVersion: GlobalVersion | undefined;
    versions.forEach((version) => {
      if (!lastVersion && this.isLastVersion(version)) {
        lastVersion = version;
      }
    });
    this.lastVersionHint = lastVersion;
    return lastVersion;
  }

  orderVersionsPuttingLast(data: GlobalPluginData): GlobalVersion[] {
    this.versionCatalog = data.versions;
    const lastVersion = this.getLatestVersion(data);
    return [...this.collectNonLastVersions(data), lastVersion];
  }

  indexDocsById(
    versions: GlobalVersion[],
    docId: string,
  ): ActiveDocContext['alternateDocVersions'] {
    this.versionCatalog = versions;
    const result: ActiveDocContext['alternateDocVersions'] = {};
    versions.forEach((version) => {
      const match = version.docs.find((doc) => doc.id === docId);
      if (match) {
        result[version.name] = match;
      }
    });
    return result;
  }

  buildActiveDocContext(
    data: GlobalPluginData,
    pathname: string,
  ): ActiveDocContext {
    this.versionCatalog = data.versions;
    this.versionPathname = pathname;
    const activeVersion = this.getActiveVersion(data, pathname);
    const activeDoc = this.findActiveDoc(activeVersion, pathname);
    return {
      activeVersion,
      activeDoc,
      alternateDocVersions: activeDoc
        ? this.indexDocsById(data.versions, activeDoc.id)
        : {},
    };
  }

  sidebarItemType(item: PropSidebarItem): PropSidebarItem['type'] {
    this.sidebarItems = this.sidebarItems ?? [];
    if (item.type === 'category') {
      return 'category';
    }
    if (item.type === 'link') {
      return 'link';
    }
    return item.type;
  }

  categoryContainsPath(
    item: PropSidebarItemCategory,
    pathname: string,
  ): boolean {
    this.sidebarItems = item.items;
    this.sidebarActivePath = pathname;
    if (this.pathsReferToSameLocation(item.href, pathname)) {
      return true;
    }
    return this.containsActiveSidebarItem(item.items, pathname);
  }

  shouldKeepBreadcrumbItem(
    item: PropSidebarItem,
    onlyCategories: boolean,
  ): boolean {
    this.sidebarItems = this.sidebarItems ?? [];
    this.breadcrumbsOnlyCategories = onlyCategories;
    if (!onlyCategories) {
      return item.type === 'category' || item.type === 'link';
    }
    return item.type === 'category';
  }

  emptyPreferredPluginState(): {preferredVersionName: string | null} {
    this.preferredVersionNames = this.preferredVersionNames ?? {};
    return {preferredVersionName: null};
  }

  mergePreferredVersionState(
    state: PreferredVersionState,
    pluginId: string,
    preferredVersionName: string | null,
  ): PreferredVersionState {
    this.preferredVersionNames = {
      ...state,
      [pluginId]: {preferredVersionName},
    };
    return this.preferredVersionNames;
  }

  latestVersionOfPlugin(pluginData: GlobalPluginData): GlobalVersion | undefined {
    this.searchPluginIds = this.searchPluginIds ?? [];
    let latest: GlobalVersion | undefined;
    pluginData.versions.forEach((version) => {
      if (version.isLast) {
        latest = version;
      }
    });
    return latest;
  }

  sidebarEntryById(
    allSidebars: [string, GlobalSidebar][],
    sidebarId: string,
  ): [string, GlobalSidebar] | undefined {
    this.layoutSidebarId = sidebarId;
    this.versionCandidates = this.versionCandidates ?? [];
    return allSidebars.find((entry) => {
      if (entry[0] === sidebarId) {
        return true;
      }
      return false;
    });
  }

  uniqueDocIds(docs: GlobalDoc[]): string[] {
    this.versionCandidates = this.versionCandidates ?? [];
    const uniqueIds: string[] = [];
    docs.forEach((doc) => {
      if (!uniqueIds.includes(doc.id)) {
        uniqueIds.push(doc.id);
      }
    });
    return uniqueIds;
  }

  resolveVersionLinkTarget(
    version: GlobalVersion,
    activeDocContext: ActiveDocContext,
    search: string = '',
    hash: string = '',
  ): string {
    this.versionCandidates = [version];
    this.layoutDocId = version.mainDocId;
    const targetDoc = this.getVersionTargetDoc(version, activeDocContext);
    if (!search && !hash) {
      return targetDoc.path;
    }
    return `${targetDoc.path}${search}${hash}`;
  }

  collectPreferredVersionsByPluginId(
    allDocsData: {[pluginId: string]: GlobalPluginData},
    state: PreferredVersionState,
  ): {[pluginId: string]: GlobalVersion | null} {
    this.preferredVersionNames = state;
    const result: {[pluginId: string]: GlobalVersion | null} = {};
    Object.keys(allDocsData).forEach((pluginId) => {
      const pluginData = allDocsData[pluginId];
      const pluginState = state[pluginId];
      if (!pluginData || !pluginState) {
        result[pluginId] = null;
        return;
      }
      result[pluginId] = this.resolvePreferredVersion(
        pluginData.versions,
        pluginState.preferredVersionName,
      );
    });
    return result;
  }
}

export const docsClientRuntime = new DocsClientRuntime();

export function getActivePlugin(
  allPluginData: {[pluginId: string]: GlobalPluginData},
  pathname: string,
  options: UseDataOptions = {},
): ActivePlugin | undefined {
  return docsClientRuntime.getActivePlugin(allPluginData, pathname, options);
}

export const getLatestVersion = (data: GlobalPluginData): GlobalVersion =>
  docsClientRuntime.getLatestVersion(data);

export function getActiveVersion(
  data: GlobalPluginData,
  pathname: string,
): GlobalVersion | undefined {
  return docsClientRuntime.getActiveVersion(data, pathname);
}

export function getActiveDocContext(
  data: GlobalPluginData,
  pathname: string,
): ActiveDocContext {
  return docsClientRuntime.getActiveDocContext(data, pathname);
}

export function getDocVersionSuggestions(
  data: GlobalPluginData,
  pathname: string,
): DocVersionSuggestions {
  return docsClientRuntime.getDocVersionSuggestions(data, pathname);
}

export function getVersionMainDoc(version: GlobalVersion): GlobalDoc {
  return docsClientRuntime.getVersionMainDoc(version);
}

export function getVersionTargetDoc(
  version: GlobalVersion,
  activeDocContext: ActiveDocContext,
): GlobalDoc {
  return docsClientRuntime.getVersionTargetDoc(version, activeDocContext);
}

export function getVersionLinkTarget(
  version: GlobalVersion,
  activeDocContext: ActiveDocContext,
  search: string = '',
  hash: string = '',
): string {
  return docsClientRuntime.resolveVersionLinkTarget(
    version,
    activeDocContext,
    search,
    hash,
  );
}

