import {fromPartial} from '@total-typescript/shoehorn';
import {getActiveVersion} from '../docsClientUtils';
import type {GlobalVersion} from '../index';

function v(partial: Partial<GlobalVersion>): GlobalVersion {
  return fromPartial<GlobalVersion>(partial);
}

const versions = [
  v({name: 'current', path: '/'}),
  v({name: 'v0.1.2', path: '/v0.1.2'}),
  v({name: 'v0.2.0', path: '/v0.2.0'}),
];

it('current version path / does not freeze active version', () => {
  expect(getActiveVersion(fromPartial({versions}), '/')?.name).toBe('current');
  expect(getActiveVersion(fromPartial({versions}), '/v0.1.2')?.name).toBe('v0.1.2');
  expect(getActiveVersion(fromPartial({versions}), '/v0.1.2/someDoc')?.name).toBe('v0.1.2');
  expect(getActiveVersion(fromPartial({versions}), '/v0.2.0/someDoc')?.name).toBe('v0.2.0');
  expect(getActiveVersion(fromPartial({versions}), '/unknown')?.name).toBe('current');
});
EOF
